INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000001, 'en', '<p>The west cardinal light buoy SAMPLE-1 in pos. 56° 48.0''N - 011° 33.0''E is unlit. This is sample content for trying Niord, not a real notice.</p>', 'Light buoy unlit', 1000001);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000002, 'da', '<p>Vestkardinal-lystønden SAMPLE-1 på pos. 56° 48,0''N - 011° 33,0''E er slukket. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Lystønde slukket', 1000001);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000003, 'en', '<p>A wreck with a least depth of 9 metres is reported in pos. 55° 19.8''N - 010° 54.0''E. Mariners are advised to keep well clear. This is sample content for trying Niord, not a real notice.</p>', 'Wreck', 1000002);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000004, 'da', '<p>Et vrag med en mindste dybde på 9 meter er meldt på pos. 55° 19,8''N - 010° 54,0''E. Skibsfarten opfordres til at holde godt klar. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Vrag', 1000002);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000005, 'en', '<p>Diving operations take place on weekdays from 0700 to 1600 in pos. 55° 42.0''N - 012° 39.6''E. The diving vessel shows the prescribed signals. Passing vessels are requested to keep clear and reduce speed. This is sample content for trying Niord, not a real notice.</p>', 'Diving operations', 1000003);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000006, 'da', '<p>Der udføres dykkerarbejde på hverdage fra kl. 0700 til 1600 på pos. 55° 42,0''N - 012° 39,6''E. Dykkerfartøjet viser de foreskrevne signaler. Passerende skibe anmodes om at holde klar og sænke farten. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Dykkerarbejde', 1000003);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000007, 'en', '<p>An empty container was reported adrift in pos. 55° 24.0''N - 014° 48.0''E. Mariners are requested to keep a sharp lookout. This is sample content for trying Niord, not a real notice.</p>', 'Object adrift', 1000004);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000008, 'da', '<p>En tom container er meldt i drift på pos. 55° 24,0''N - 014° 48,0''E. Skibsfarten anmodes om at holde skarpt udkig. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Genstand i drift', 1000004);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000009, 'en', '<p>The RACON on the light buoy SAMPLE-2 in pos. 57° 45.0''N - 010° 36.0''E is out of service. This is sample content for trying Niord, not a real notice.</p>', 'RACON out of service', 1000005);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000010, 'da', '<p>RACON''en på lystønden SAMPLE-2 på pos. 57° 45,0''N - 010° 36,0''E er ude af drift. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'RACON ude af drift', 1000005);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000011, 'en', '<p>Cable laying takes place between pos. 55° 30.0''N - 009° 43.2''E and pos. 55° 28.8''N - 009° 45.6''E. The cable vessel is restricted in her ability to manoeuvre. This is sample content for trying Niord, not a real notice.</p>', 'Cable operations', 1000006);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000012, 'da', '<p>Der udlægges kabel mellem pos. 55° 30,0''N - 009° 43,2''E og pos. 55° 28,8''N - 009° 45,6''E. Kabelfartøjet er begrænset i sin manøvreevne. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Kabelarbejde', 1000006);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000013, 'en', '<p>The green buoy SAMPLE-3 in pos. 54° 57.0''N - 010° 24.0''E is missing. This is sample content for trying Niord, not a real notice.</p>', 'Buoy missing', 1000007);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000014, 'da', '<p>Den grønne tønde SAMPLE-3 på pos. 54° 57,0''N - 010° 24,0''E er savnet. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Tønde savnet', 1000007);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000015, 'en', '<p>A survey vessel carries out hydrographic survey in the area shown. Passing vessels are requested to give it a wide berth. This is sample content for trying Niord, not a real notice.</p>', 'Hydrographic survey', 1000008);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000016, 'da', '<p>Et opmålingsfartøj udfører opmåling i det viste område. Passerende skibe anmodes om at give god plads. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Opmåling', 1000008);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000017, 'en', '<p>Seabed survey with towed equipment takes place in the area shown. The survey vessel is restricted in her ability to manoeuvre. This is sample content for trying Niord, not a real notice.</p>', 'Underwater survey', 1000009);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000018, 'da', '<p>Der udføres havbundsundersøgelse med slæbt udstyr i det viste område. Fartøjet er begrænset i sin manøvreevne. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Havbundsundersøgelse', 1000009);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000019, 'en', '<p>Salvage operations took place in pos. 54° 58.8''N - 011° 37.2''E. This is sample content for trying Niord, not a real notice.</p>', 'Salvage operations', 1000010);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000020, 'da', '<p>Der blev udført bjærgningsarbejde på pos. 54° 58,8''N - 011° 37,2''E. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Bjærgningsarbejde', 1000010);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000021, 'en', '<p>The light SAMPLE-4 in pos. 56° 10.2''N - 012° 18.0''E was unreliable. The warning is cancelled. This is sample content for trying Niord, not a real notice.</p>', 'Light unreliable', 1000011);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000022, 'da', '<p>Fyret SAMPLE-4 på pos. 56° 10,2''N - 012° 18,0''E var upålideligt. Advarslen er annulleret. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Fyr upålideligt', 1000011);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000023, 'en', '<p>A naval exercise was planned in the area shown. The draft was deleted. This is sample content for trying Niord, not a real notice.</p>', 'Exercise', 1000012);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000024, 'da', '<p>En flådeøvelse var planlagt i det viste område. Udkastet blev slettet. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Øvelse', 1000012);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000025, 'en', '<p>The bascule bridge SAMPLE-5 in pos. 55° 40.5''N - 012° 35.7''E is closed for passage on weekdays from 0700 to 1500 because of maintenance. This is sample content for trying Niord, not a real notice.</p>', 'Bridge closed for passage', 1000013);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000026, 'da', '<p>Klapbroen SAMPLE-5 på pos. 55° 40,5''N - 012° 35,7''E er lukket for gennemsejling på hverdage fra kl. 0700 til 1500 på grund af vedligeholdelse. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Bro lukket for gennemsejling', 1000013);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000027, 'en', '<p>The red buoy SAMPLE-6 is reported off station in pos. 57° 03.3''N - 009° 56.1''E. This is sample content for trying Niord, not a real notice.</p>', 'Buoy off station', 1000014);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000028, 'da', '<p>Den røde tønde SAMPLE-6 er meldt ude af position på pos. 57° 03,3''N - 009° 56,1''E. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Tønde ude af position', 1000014);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000029, 'en', '<p>A north cardinal light buoy, SAMPLE-7, Q, has been established in pos. 55° 58.8''N - 010° 51.0''E. This is sample content for trying Niord, not a real notice.</p>', 'Light buoy established', 1000015);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000030, 'da', '<p>En nordkardinal-lystønde, SAMPLE-7, Q, er udlagt på pos. 55° 58,8''N - 010° 51,0''E. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Lystønde udlagt', 1000015);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000031, 'en', '<p>The red buoy SAMPLE-8 in pos. 54° 57.0''N - 010° 57.0''E has been permanently withdrawn. This is sample content for trying Niord, not a real notice.</p>', 'Buoy withdrawn', 1000016);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000032, 'da', '<p>Den røde tønde SAMPLE-8 på pos. 54° 57,0''N - 010° 57,0''E er inddraget permanent. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Tønde inddraget', 1000016);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000033, 'en', '<p>The light structure SAMPLE-9 in pos. 56° 01.8''N - 012° 37.2''E is damaged. The light shows with reduced range until repaired. This is sample content for trying Niord, not a real notice.</p>', 'Light damaged', 1000017);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000034, 'da', '<p>Fyrkonstruktionen SAMPLE-9 på pos. 56° 01,8''N - 012° 37,2''E er beskadiget. Fyret viser med nedsat lysvidde, indtil det er repareret. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Fyr beskadiget', 1000017);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000035, 'en', '<p>A depth of 6.2 metres, less than charted, has been found in the area shown. This is sample content for trying Niord, not a real notice.</p>', 'Reduced depth', 1000018);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000036, 'da', '<p>Der er fundet en vanddybde på 6,2 meter, mindre end angivet i søkortet, i det viste område. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Mindre vanddybde', 1000018);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000037, 'en', '<p>A hydrographic survey of the area shown is planned for November and December, after the cable operations of NW-006-26. This is sample content for trying Niord, not a real notice.</p>', 'Planned hydrographic survey', 1000019);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000038, 'da', '<p>En opmåling af det viste område er planlagt i november og december, efter kabelarbejdet i NW-006-26. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Planlagt opmåling', 1000019);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000039, 'en', '<p>A temporary AIS station in pos. 54° 51.0''N - 012° 09.0''E transmits test messages. The messages may be disregarded. This is sample content for trying Niord, not a real notice.</p>', 'AIS test transmissions', 1000020);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000040, 'da', '<p>En midlertidig AIS-station på pos. 54° 51,0''N - 012° 09,0''E udsender testmeddelelser. Meddelelserne kan ses bort fra. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'AIS-testudsendelser', 1000020);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000041, 'en', '<p>The beacon SAMPLE-10 in pos. 54° 37.2''N - 012° 03.0''E is damaged. This is sample content for trying Niord, not a real notice.</p>', 'Beacon damaged', 1000021);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000042, 'da', '<p>Båken SAMPLE-10 på pos. 54° 37,2''N - 012° 03,0''E er beskadiget. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Båke beskadiget', 1000021);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000043, 'en', '<p>A seabed survey of the area shown is planned for the spring. This is sample content for trying Niord, not a real notice.</p>', 'Planned seabed survey', 1000022);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000044, 'da', '<p>En havbundsundersøgelse af det viste område er planlagt i foråret. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Planlagt havbundsundersøgelse', 1000022);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000045, 'en', '<p>The light buoy SAMPLE-11 in pos. 55° 03.0''N - 010° 37.2''E has been temporarily replaced by an unlit buoy. This is sample content for trying Niord, not a real notice.</p>', 'Light buoy replaced', 1000023);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000046, 'da', '<p>Lystønden SAMPLE-11 på pos. 55° 03,0''N - 010° 37,2''E er midlertidigt erstattet af en tønde uden lys. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Lystønde erstattet', 1000023);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000047, 'en', '<p>The buoy SAMPLE-12 was off station in pos. 55° 12.0''N - 011° 14.1''E. It has been put back. This is sample content for trying Niord, not a real notice.</p>', 'Buoy off station', 1000024);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000048, 'da', '<p>Tønden SAMPLE-12 var ude af position på pos. 55° 12,0''N - 011° 14,1''E. Den er lagt på plads igen. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Tønde ude af position', 1000024);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000049, 'en', '<p>The beacon SAMPLE-13 in pos. 56° 57.0''N - 009° 03.0''E was reported missing. The notice is cancelled. This is sample content for trying Niord, not a real notice.</p>', 'Beacon missing', 1000025);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000050, 'da', '<p>Båken SAMPLE-13 på pos. 56° 57,0''N - 009° 03,0''E blev meldt savnet. Efterretningen er annulleret. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Båke savnet', 1000025);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000051, 'en', '<p>An uncharted obstruction was reported in pos. 57° 13.2''N - 010° 42.0''E. The draft was deleted. This is sample content for trying Niord, not a real notice.</p>', 'Uncharted obstruction', 1000026);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000052, 'da', '<p>En ukortlagt hindring blev meldt på pos. 57° 13,2''N - 010° 42,0''E. Udkastet blev slettet. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Ukortlagt hindring', 1000026);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000053, 'en', '<p>Firing exercises take place in the firing area EK R 11 Sjællands Odde W. on the days announced. The area is shown on the map. Ships are requested to keep clear while the warning flags are hoisted. This is sample content for trying Niord, not a real notice.</p>', 'Firing exercises', 1000027);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000054, 'da', '<p>Der afholdes skydeøvelser i skydeområdet EK R 11 Sjællands Odde W. på de bekendtgjorte dage. Området er vist på kortet. Skibe anmodes om at holde klar, mens advarselsflagene er hejst. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Skydeøvelser', 1000027);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000055, 'en', '<p>Firing exercises take place in the firing area EK D 389 Skagen N. on the days announced. The area is shown on the map. Ships are requested to keep clear while the warning flags are hoisted. This is sample content for trying Niord, not a real notice.</p>', 'Firing exercises', 1000028);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000056, 'da', '<p>Der afholdes skydeøvelser i skydeområdet EK D 389 Skagen N. på de bekendtgjorte dage. Området er vist på kortet. Skibe anmodes om at holde klar, mens advarselsflagene er hejst. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Skydeøvelser', 1000028);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000057, 'en', '<p>Firing exercises take place in the firing area EK D 371 Marstal Bugt on the days announced. The area is shown on the map. Ships are requested to keep clear while the warning flags are hoisted. This is sample content for trying Niord, not a real notice.</p>', 'Firing exercises', 1000029);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000058, 'da', '<p>Der afholdes skydeøvelser i skydeområdet EK D 371 Marstal Bugt på de bekendtgjorte dage. Området er vist på kortet. Skibe anmodes om at holde klar, mens advarselsflagene er hejst. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Skydeøvelser', 1000029);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000059, 'en', '<p>Firing exercises take place in the firing area EK R 33 Vejers on the days announced. The area is shown on the map. Ships are requested to keep clear while the warning flags are hoisted. This is sample content for trying Niord, not a real notice.</p>', 'Firing exercises', 1000030);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000060, 'da', '<p>Der afholdes skydeøvelser i skydeområdet EK R 33 Vejers på de bekendtgjorte dage. Området er vist på kortet. Skibe anmodes om at holde klar, mens advarselsflagene er hejst. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Skydeøvelser', 1000030);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000061, 'en', '<p>Fl = flashing, Q = quick flashing, Oc = occulting, Iso = isophase, F = fixed. The list is an example of almanac content. This is sample content for trying Niord, not a real notice.</p>', 'Abbreviations', 1000031);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000062, 'da', '<p>Fl = blink, Q = hurtigblink, Oc = formørkelser, Iso = isofase, F = fast. Listen er et eksempel på almanakindhold. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Forkortelser', 1000031);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000063, 'en', '<p>Mariners who observe a hazard to navigation are asked to report it to the nearest coast radio station. The text is an example of almanac content. This is sample content for trying Niord, not a real notice.</p>', 'Reporting a hazard', 1000032);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000064, 'da', '<p>Søfarende, der observerer en fare for sejladsen, bedes melde den til nærmeste kystradiostation. Teksten er et eksempel på almanakindhold. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Indberetning af fare', 1000032);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000065, 'en', '<p>The attached overview shows where the sample''s firing areas lie. The annex is an example of annex content. This is sample content for trying Niord, not a real notice.</p>', 'Firing areas', 1000033);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000066, 'da', '<p>Den vedhæftede oversigt viser, hvor eksemplets skydeområder ligger. Bilaget er et eksempel på bilagsindhold. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Skydeområder', 1000033);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000067, 'en', '<p>The annex explains how the chart corrections of the notices are to be read. The text is an example of annex content. This is sample content for trying Niord, not a real notice.</p>', 'Chart corrections', 1000034);
INSERT INTO public."MessagePartDesc" (id, lang, details, subject, entity_id) VALUES (1000068, 'da', '<p>Bilaget forklarer, hvordan efterretningernes søkortrettelser skal læses. Teksten er et eksempel på bilagsindhold. Dette er eksempelindhold til at prøve Niord, ikke en rigtig efterretning.</p>', 'Søkortrettelser', 1000034);
